// ?expire@Rva002A0450Owner@@QAEHXZ
// partial score=0.68 date=2026-09-16
// cl: /O2 /Ob1 /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHs-c-
//
// Retail 0x002A0450 watches a deadline frame held at +0x10 of the owner. Once
// the logic frame passes it the body marks itself done, clears one status bit
// on the object stored eight bytes below the owner, sets another, and reapplies
// the condition set through the pinned BfmeOwnerVNI::bfmeApply1VNI helper at
// ILT 0x0002191D. The owner name is address-derived because no vtable slot and
// no named caller reach ILT 0x0001825F.

extern "C" void _ReadWriteBarrier( void );
#pragma intrinsic( _ReadWriteBarrier )

typedef unsigned int UnsignedInt;
typedef int Int;
typedef unsigned char Bool;

class BfmeOwnerVNI
{
public:
	void bfmeApply1VNI();
};

class GameLogic
{
public:
	unsigned char m_bfmePad000[ 0x3c ];
	UnsignedInt m_bfmeFrame;
};

extern GameLogic *TheBfmeGameLogic;

class Rva002A0450Target
{
public:
	unsigned char m_bfmePad000[ 0x118 ];
	volatile UnsignedInt m_bfmeFlags;
};

class Rva002A0450Owner
{
public:
	Int expire();

private:
	unsigned char m_bfmePad000[ 0x10 ];
	UnsignedInt m_bfmeDeadline;
	Bool m_bfmeDone;
};

static inline void bfmeStoreTwiceVNI( volatile UnsignedInt *slot, UnsignedInt first,
	UnsignedInt second )
{
	*slot = first;
	*slot = second;
}

Int Rva002A0450Owner::expire()
{
	UnsignedInt deadline = m_bfmeDeadline;

	if( deadline == 0 )
		return 1;

	if( m_bfmeDone == 1 )
		return 1;

	if( TheBfmeGameLogic->m_bfmeFrame <= deadline )
		return 1;

	m_bfmeDone = 1;
	m_bfmeDeadline = 0;

	Rva002A0450Target *target = *(Rva002A0450Target **)( (char *)this - 8 );

	UnsignedInt flags = target->m_bfmeFlags;

	if( ( flags & 0x400 ) == 0 && ( flags & 0x800 ) != 0 )
		return 1;

	UnsignedInt cleared = target->m_bfmeFlags & ~0x400;
	target->m_bfmeFlags = cleared;
	target->m_bfmeFlags = cleared | 0x800;
	( (BfmeOwnerVNI *)target )->bfmeApply1VNI();
	return 1;
}
